import React from 'react';
import { Alert } from 'react-bootstrap';

function AlertMsg(props) {
  const capitalize = (word) => {
    const lower = word.toLowerCase();
    return lower.charAt(0).toUpperCase() + lower.slice(1);
  }
    return (
       props.alert && <Alert id='alert' className='text-center mx-5 border border-5' variant={`${props.alert.type} + ${props.alert.border}`}>
          <p>
            {capitalize(props.alert.type)}: {props.alert.msg}  
          </p>
          if (props.alert.type == "warning"){
              props.alert.border == "border-danger"
            } else props.alert.border == "border-success"
        </Alert>
      );
    }


export default AlertMsg;
